        if (au()) A.pad(CHORDS[chordI++ % CHORDS.length].map(n => A.note(n)), { dur: 9.5, vol: 0.075 * (1 - 0.5 * dim) * (1 - endK), attack: 2.6, lp: 850 });
        S.later(padLoop, 7600 + doneCount * 120);
